# scripts/quality_hotspots.py
"""
Identifies the worst files across all dimensions.
Produces a ranked list for Sprint planning.
High complexity + low type coverage + security findings
= highest priority cleanup target.
"""
import json
import subprocess
from pathlib import Path

def get_complex_files(n: int = 10) -> list[dict]:
    """Top N files by average cyclomatic complexity."""
    result = subprocess.run(
        ["radon", "cc", ".", "-j"],
        capture_output=True, text=True
    )
    data = json.loads(result.stdout)
    file_scores = []
    for filepath, blocks in data.items():
        if not blocks:
            continue
        avg = sum(b["complexity"] for b in blocks) / len(blocks)
        max_cc = max(b["complexity"] for b in blocks)
        file_scores.append({
            "file": filepath,
            "avg_complexity": round(avg, 2),
            "max_complexity": max_cc,
            "block_count": len(blocks),
            "worst_function": max(
                blocks, key=lambda b: b["complexity"]
            )["name"]
        })
    return sorted(
        file_scores,
        key=lambda x: x["avg_complexity"],
        reverse=True
    )[:n]

def get_untyped_files(n: int = 10) -> list[dict]:
    """Top N files with lowest type annotation coverage."""
    result = subprocess.run(
        ["mypy", ".", "--ignore-missing-imports",
         "--any-exprs-report", "/tmp/mypy_any"],
        capture_output=True, text=True
    )
    any_report = Path("/tmp/mypy_any/any-exprs.txt")
    if not any_report.exists():
        return []

    file_scores = []
    for line in any_report.read_text().splitlines()[1:]:
        parts = line.split()
        if len(parts) >= 3:
            file_scores.append({
                "file": parts[0],
                "any_count": int(parts[1]),
                "total_exprs": int(parts[2]),
                "any_pct": round(
                    int(parts[1]) / max(int(parts[2]), 1) * 100, 1
                )
            })
    return sorted(
        file_scores,
        key=lambda x: x["any_pct"],
        reverse=True
    )[:n]

def get_security_hotspots() -> list[dict]:
    """Files with HIGH severity Bandit findings."""
    result = subprocess.run(
        ["bandit", "-r", ".", "-f", "json"],
        capture_output=True, text=True
    )
    data = json.loads(result.stdout)
    high = [
        {
            "file": r["filename"],
            "line": r["line_number"],
            "issue": r["issue_text"],
            "severity": r["issue_severity"],
            "confidence": r["issue_confidence"]
        }
        for r in data.get("results", [])
        if r["issue_severity"] == "HIGH"
    ]
    return sorted(high, key=lambda x: x["file"])

def generate_hotspot_report() -> dict:
    report = {
        "complex_files":    get_complex_files(10),
        "untyped_files":    get_untyped_files(10),
        "security_hotspots": get_security_hotspots(),
    }

    # Cross-reference: files that appear in 2+ categories
    complex_set  = {f["file"] for f in report["complex_files"]}
    untyped_set  = {f["file"] for f in report["untyped_files"]}
    security_set = {f["file"] for f in report["security_hotspots"]}

    critical_files = (
        complex_set & untyped_set |
        complex_set & security_set |
        untyped_set & security_set
    )

    report["critical_files"] = sorted(critical_files)
    report["critical_file_count"] = len(critical_files)
    return report

if __name__ == "__main__":
    report = generate_hotspot_report()
    Path("reports/hotspots.json").write_text(
        json.dumps(report, indent=2)
    )
    print(f"\n🔥 Critical files (appear in 2+ categories):")
    for f in report["critical_files"]:
        print(f"  {f}")
    print(f"\nTotal: {report['critical_file_count']} files need priority attention")
